// Inverse of the user-focus clarification, only for historical prompt fingerprints.
export const restoreUserFocusRule = (content: string) => content.replace(
  /Those fields judge the reply's usefulness for the User's own present experience[^\n]+?These fields also judge whether an invitation is gentle\/easy to decline, and other contradictions\./gu,
  "Those fields judge the reply's contextual usefulness under the support-function definition, whether an invitation is gentle/easy to decline, and other contradictions."
);

export const restoreRepair1Rules = (content: string) => {
  content = restoreUserFocusRule(content);
  for (const [current, previous] of REPAIR2_RULE_EDITS) content = content.split(current).join(previous);
  return content;
};

export const restoreFirstFollowupRules = (content: string) => {
  content = restoreRepair1Rules(content);
  for (const [current, previous] of REPAIR1_RULE_EDITS) content = content.split(current).join(previous);
  return content;
};

export const restoreExplicitAffectRules = (content: string) => {
  assert.equal(content.split(CONTEXTUAL_ACCEPTANCE_SNAPSHOT).length - 1, 1);
  content = content.replace(CONTEXTUAL_ACCEPTANCE_SNAPSHOT + "\n", "")
    .replace(/drift, generic reassurance, advice/g, "drift, reassurance, advice");
  content = restoreFirstFollowupRules(content);
  for (const [current, historical] of FOLLOWUP_RULE_EDITS) content = content.split(current).join(historical);
  const lines = content.split("\n");
  const boundaryLines = lines.filter((line) => line.startsWith("Affect interpretation boundary:"));
  assert.deepEqual(boundaryLines, [AFFECT_INTERPRETATION_BOUNDARY], "Exactly the declared new boundary reaches the judge.");
  let restored = lines.filter((line) => line !== AFFECT_INTERPRETATION_BOUNDARY).join("\n");
  const relational = lines.some((line) => line.startsWith("affectObservation, for "));
  assert.equal(restored.split(RELATIONAL_AFFECT_DRIFT_RULE).length - 1, relational ? 1 : 0,
    "Exactly the declared relational definition reaches the judge.");
  restored = restored.replace(RELATIONAL_AFFECT_DRIFT_RULE, PREVIOUS_OBSERVED_AFFECT_DRIFT_RULE);
  for (const [prefix, addition] of [
    ["affectObservation, for ", ATTRIBUTION_RULE_CLARIFICATIONS.relationalAffect],
    ["affectObservation, for ", AFFECT_EVIDENCE_RULE],
    ["ES-SCOPE: ", ATTRIBUTION_RULE_CLARIFICATIONS.scope],
    ["ES-ACK-NO-FABRICATION: ", ATTRIBUTION_RULE_CLARIFICATIONS.assistantHistory],
  ]) {
    const applicable = lines.some((line) => line.startsWith(prefix));
    assert.equal(restored.split(addition).length - 1, applicable ? 1 : 0,
      `Exactly the declared attribution clarification accompanies ${prefix}`);
    restored = restored.replace(addition, "");
  }
  for (const [current, historical] of AFFECT_RULE_EDITS) restored = restored.split(current).join(historical);
  return restored;
};
